UPDATE product_specifications s
JOIN products p ON p.id = s.product_id AND p.data_version = 'catalog-expansion-2025-v1'
JOIN (
    SELECT patch.sku, patch.model, JSON_ARRAYAGG(field.parameter_data) AS parameters
    FROM JSON_TABLE(@catalog_parameter_patches, '$[*]' COLUMNS (
        sku VARCHAR(80) PATH '$[0]', model VARCHAR(100) PATH '$[1]', parameters JSON PATH '$[2]',
        expected JSON PATH '$[3]'
    )) patch
    JOIN products existing ON existing.sku = patch.sku AND BINARY existing.model = BINARY patch.model
    JOIN product_specifications old ON old.product_id = existing.id AND JSON_CONTAINS(old.parameters, patch.expected)
    JOIN JSON_TABLE(patch.parameters, '$[*]' COLUMNS (
        code VARCHAR(60) PATH '$.code', parameter_data JSON PATH '$'
    )) field
    GROUP BY patch.sku, patch.model
    HAVING SUM(JSON_SEARCH(old.parameters, 'one', field.code, NULL, '$[*].code') IS NOT NULL) = 0
) supplemental ON supplemental.sku = p.sku AND BINARY supplemental.model = BINARY p.model
SET s.parameters = JSON_MERGE_PRESERVE(s.parameters, supplemental.parameters),
    p.revision = p.revision + 1;

COMMIT;
